import { mkdirSync, writeFileSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
import { compile } from 'sass';

const source = resolve(process.cwd(), 'src/styles/widget.scss');
const target = resolve(process.cwd(), 'src/styles/widget.generated.ts');

const { css } = compile(source, { style: 'compressed', loadPaths: [dirname(source)] });

mkdirSync(dirname(target), { recursive: true });
writeFileSync(
  target,
  [
    '// Generated by scripts/build-styles.ts from widget.scss. Do not edit.',
    `export const widgetCss = ${JSON.stringify(css)};`,
    '',
  ].join('\n'),
);

process.stdout.write(`styles compiled: ${css.length} bytes\n`);
